#include <iostream>
#include <vector>
#include <stdexcept>

int estimar(int piezas) {
    if (piezas < 0 || piezas > 10) {
        throw std::invalid_argument{"Quantity outside 0 to 10"};
    }
    if (piezas == 0) { return 0; }
    return 3 + 2 * piezas;
}

int main() {
    std::vector<int> pedidos{2, 11, 3};
    int aceptados{0};
    int total{0};
    try {
        for (int piezas : pedidos) {
            int minutos{estimar(piezas)};
            ++aceptados;
            total += minutos;
        }
    } catch (const std::invalid_argument& error) {
        std::cout << "Stopped:";
    }
    std::cout << aceptados << ":" << total;
    return 0;
}

